package com.delivery.platform.payments.api;import com.delivery.platform.common.ApiException;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/webhooks/payments")public class PaymentWebhookController{private final JdbcClient db;private final String secret;PaymentWebhookController(JdbcClient db,@Value("${PAYMENT_WEBHOOK_SECRET:local-simulated-secret}")String secret){this.db=db;this.secret=secret;}public record Webhook(String externalEventId,String eventType,UUID tenantId,UUID paymentId,String status){}@PostMapping("/{provider}")@ResponseStatus(HttpStatus.ACCEPTED)Map<String,String> receive(@PathVariable String provider,@RequestHeader(value="X-Webhook-Signature",required=false)String signature,@RequestBody Webhook q){if(!secret.equals(signature))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_WEBHOOK_SIGNATURE","Firma inválida");if(db.sql("select count(*) from payment_webhook_events where provider=:p and external_event_id=:e").param("p",provider).param("e",q.externalEventId()).query(Integer.class).single()==0)db.sql("insert into payment_webhook_events(id,tenant_id,provider,external_event_id,event_type,payload,status,processed_at) values(gen_random_uuid(),:t,:p,:e,:y,jsonb_build_object('paymentId',:i,'status',:s),'PROCESSED',now())").param("t",q.tenantId()).param("p",provider).param("e",q.externalEventId()).param("y",q.eventType()).param("i",q.paymentId().toString()).param("s",q.status()).update();return Map.of("status","accepted");}}
